package com.mutqan.hadith.data

import android.content.Context
import androidx.test.core.app.ApplicationProvider
import com.mutqan.hadith.data.seed.SeedLoader
import java.io.File
import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

/**
 * The seed is scholarly text, so none of it may be typed in or recalled: it is generated by `tools/import_hadiths.py`
 * from an open dataset, and `tools/data/source_snapshot.json` keeps the source records it was generated from.
 * These tests hold the seed to that: it is structurally sound, complete, and every matn, narrator and chain order
 * can be found in the source text of its own record.
 *
 * The catalog is the Forty Hadith of an-Nawawi alone; the Bukhari selection and 'Umdat al-Ahkam of the earlier catalogs
 * were retired in catalog 4, and catalog 5 files the hadiths in groups, the books and sections the library is browsed by.
 */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34])
class SeedDataIntegrityTest {

    private val context: Context = ApplicationProvider.getApplicationContext()
    private val seed = SeedLoader.load(context)
    private val raw = JSONObject(File("src/main/assets/seed_hadiths.json").readText(Charsets.UTF_8))
    private val snapshot = JSONObject(File("../tools/data/source_snapshot.json").readText(Charsets.UTF_8))
    private val selection = JSONObject(File("../tools/data/selection.json").readText(Charsets.UTF_8))

    private val narrators = seed.narrators.associateBy { it.id }
    private val edgesByHadith = seed.edges.groupBy { it.hadithId }.mapValues { (_, edges) -> edges.sortedBy { it.orderIndex } }
    private val rawByHadith = raw.getJSONArray("hadiths").objects().associateBy { it.getLong("id") }
    private val arbain = snapshot.getJSONObject("arbain")

    private fun JSONArray.objects() = List(length()) { getJSONObject(it) }

    /** Letters only, folded and single-spaced: the form in which a text is compared with its source (as in the importer). */
    private fun letters(text: String): String =
        text.replace(Regex("[\\u0610-\\u061A\\u064B-\\u065F\\u0670\\u06D6-\\u06ED\\u200b-\\u200f\\u202a-\\u202e\\u2066-\\u2069\\ufeff\\u0640]"), "")
            .replace('أ', 'ا').replace('إ', 'ا').replace('آ', 'ا').replace('ٱ', 'ا')
            .replace('ى', 'ي').replace('ة', 'ه').replace('ؤ', 'و').replace('ئ', 'ي')
            .replace(Regex("[^\\u0621-\\u064A]+"), " ").trim()

    /** The same spelling for every way the sources write `عبد الله` and a kunya (`أبو`/`أبي`/`أبا`). */
    private fun comparable(text: String): String =
        letters(text)
            .replace(Regex("\\s+وقيل\\s+\\S+\\s+\\S+(?=\\s+\\S+\\s+بن(\\s|$))"), "")
            .replace(Regex("(^|\\s)عبد(ال)"), "$1عبد $2")
            .replace(Regex("(^|\\s)اب[يا](?=\\s|$)"), "$1ابو")

    private fun sourceTextOf(hadith: com.mutqan.hadith.data.entity.HadithEntity): String =
        arbain.getJSONObject(hadith.hadithNumber.toString()).getString("text")

    @Test
    fun theSeedMatchesTheCatalogVersionTheAppExpects() {
        assertEquals(SeedLoader.CATALOG_VERSION, raw.getInt("catalogVersion"))
    }

    @Test
    fun theSeedIsTheFortyTwoHadithOfAnNawawiAndNothingElse() {
        assertEquals((1..42).toList(), seed.hadiths.map { it.hadithNumber }.sorted())
        assertTrue(seed.hadiths.all { it.level == 1 })
        assertEquals(arbain.length(), seed.hadiths.size)
    }

    @Test
    fun everyHadithIsComplete() {
        seed.hadiths.forEach { h ->
            val label = "${h.sourceBook} ${h.hadithNumber}"
            assertTrue("$label: matn", h.matnWithTashkeel.isNotBlank())
            assertTrue("$label: sahabi", h.sahabi.isNotBlank())
            assertTrue("$label: takhrij", h.takhrij.isNotBlank())
            assertTrue("$label: number", h.hadithNumber > 0)
            assertTrue("$label: matnClean is the normalized matn", h.matnClean.isNotBlank() && !h.matnClean.contains('َ'))
            assertEquals("$label: book", "الأربعون النووية", h.sourceBook)
            // The compiler at the head of the chain is the author of the book the chain is read from, else the author himself.
            assertEquals("$label: compiler", if (h.sanadSource.isBlank()) "النووي" else collectorOf.getValue(h.sanadSource), h.collector)
        }
        assertEquals("a hadith is identified by its book and number", seed.hadiths.size, seed.hadiths.map { it.sourceBook to it.hadithNumber }.toSet().size)
        assertEquals(seed.hadiths.size, seed.hadiths.map { it.id }.toSet().size)
    }

    @Test
    fun theMatnCarriesItsTashkeel() {
        seed.hadiths.forEach { h ->
            val marks = h.matnWithTashkeel.count { it in 'ً'..'ٟ' || it == 'ٰ' }
            val letters = h.matnWithTashkeel.count { it in 'ء'..'ي' }
            assertTrue("${h.sourceBook} ${h.hadithNumber}: only $marks marks on $letters letters", marks * 100 >= letters * 35)
        }
    }

    @Test
    fun everyMatnIsTheTextOfItsSourceRecord() {
        seed.hadiths.forEach { h ->
            val source = letters(sourceTextOf(h))
            assertTrue("${h.sourceBook} ${h.hadithNumber}: the matn is not in its source", source.contains(letters(h.matnWithTashkeel)))
            // Nothing of the record is cut short: after the matn there is only the author's takhrij note.
            val after = source.substring(source.indexOf(letters(h.matnWithTashkeel)) + letters(h.matnWithTashkeel).length).trim()
            val note = rawByHadith.getValue(h.id).getJSONObject("source").optString("takhrijNote")
            assertEquals("${h.sourceBook} ${h.hadithNumber}: what follows the matn", letters(note), after)
        }
    }

    @Test
    fun everyChainEndsWithTheCompanionTheAuthorNames() {
        seed.hadiths.forEach { h ->
            val label = "${h.sourceBook} ${h.hadithNumber}"
            val chain = edgesByHadith[h.id].orEmpty()
            assertTrue("$label: a chain", chain.isNotEmpty())
            assertEquals("$label: positions run 0..n-1", chain.indices.toList(), chain.map { it.orderIndex })
            assertTrue("$label: unknown narrator", chain.all { it.narratorId in narrators })
            assertTrue("$label: transmission term", chain.all { it.transmissionTerm.isNotBlank() })
            assertEquals("$label: a narrator twice", chain.size, chain.map { it.narratorId }.toSet().size)
            assertEquals("$label: the chain ends with the Sahabi", h.sahabi, narrators.getValue(chain.last().narratorId).primaryName)

            val source = " ${comparable(sourceTextOf(h))} "
            val companion = comparable(h.sahabi)
            assertTrue("$label: $companion is not in the source", source.indexOf(" $companion ") >= 0)
        }
    }

    @Test
    fun aHadithWithNoNarrationInTheSixBooksKeepsTheCompanionAloneAndNamesNoBook() {
        val withChain = snapshot.getJSONObject("narrations").keys().asSequence().map { it.toInt() }.toSet()
        seed.hadiths.filter { it.hadithNumber !in withChain }.forEach { h ->
            val label = "${h.sourceBook} ${h.hadithNumber}"
            assertEquals("$label: the Companion alone", 1, edgesByHadith[h.id].orEmpty().size)
            assertEquals("$label: no book", "", h.sanadSource)
            assertEquals("$label: compiled by the author", "النووي", h.collector)
            assertTrue("$label: no chain is cited", !rawByHadith.getValue(h.id).getJSONObject("source").has("chain"))
        }
    }

    @Test
    fun aLongChainIsTheIsnadOfANarrationInTheBookItNamesInTheOrderOfThatIsnad() {
        val narrations = snapshot.getJSONObject("narrations")
        val chosen = selection.getJSONObject("narrations")
        assertEquals("the snapshot holds the narrations the selection names", chosen.keys().asSequence().toSet(), narrations.keys().asSequence().toSet())
        assertTrue("the Forty Hadith have long chains", narrations.length() > 0)
        seed.hadiths.filter { it.hadithNumber.toString() in narrations.keys().asSequence().toSet() }.forEach { h ->
            val label = "${h.sourceBook} ${h.hadithNumber}"
            val record = narrations.getJSONObject(h.hadithNumber.toString())
            val folder = record.getString("file").substringBefore('/')
            assertEquals("$label: the book", bookOf.getValue(folder), h.sanadSource)
            assertEquals("$label: the compiler at the head of the chain", collectorOf.getValue(h.sanadSource), h.collector)
            val cited = rawByHadith.getValue(h.id).getJSONObject("source").getJSONObject("chain")
            assertEquals("$label: the cited file", record.getString("file"), cited.getString("file"))
            assertEquals("$label: the cited number", record.getInt("hadithNumber"), cited.getInt("hadithNumber"))

            val chain = edgesByHadith.getValue(h.id)
            assertTrue("$label: a chain of more than the Companion", chain.size > 1)
            // Every word of every narrator is in the isnad, in the order of the chain; the Companion is named as the author does.
            val isnad = words(record.getString("isnad"))
            var at = 0
            chain.dropLast(1).forEach { link ->
                words(narrators.getValue(link.narratorId).primaryName).forEach { word ->
                    val found = isnad.subList(at, isnad.size).indexOf(word)
                    assertTrue("$label: «$word» of ${narrators.getValue(link.narratorId).primaryName} is not in the isnad after the narrator before", found >= 0)
                    at += found + 1
                }
            }
            // The wording the chain belongs to is the wording the author quotes.
            val matn = wording(record.getString("matn"))
            val ours = wording(h.matnWithTashkeel)
            assertTrue("$label: the narration does not hold the author's wording", sharedWords(ours, matn) >= ours.size * (if (namesCollector(folder, h.takhrij)) 0.85 else 0.99))
        }
    }

    private val bookOf = mapOf(
        "Bukhari" to "صحيح البخاري", "Muslim" to "صحيح مسلم", "Tirmizi" to "سنن الترمذي",
        "IbnMaja" to "سنن ابن ماجه", "AbuDaud" to "سنن أبي داود", "Nesai" to "سنن النسائي",
    )
    private val collectorOf = mapOf(
        "صحيح البخاري" to "البخاري", "صحيح مسلم" to "مسلم", "سنن الترمذي" to "الترمذي",
        "سنن ابن ماجه" to "ابن ماجه", "سنن أبي داود" to "أبو داود", "سنن النسائي" to "النسائي",
    )

    /** The words of a text in the form names are compared in (the importer's `words_in_order`). */
    private fun words(text: String): List<String> =
        letters(text).replace(Regex("(^|\\s)عبد(ال)"), "$1عبد $2").split(" ").filter { it.isNotEmpty() }
            .map { if (it == "ابن") "بن" else if (it == "ابي" || it == "ابا") "ابو" else it }

    /** The words of a matn that tell one wording from another: the blessings a book may or may not write are left out. */
    private fun wording(text: String): List<String> =
        letters(text).replace(Regex("صلي الله عليه و ?سلم|رضي الله عن(ه|ها|هما|هم)|عليه السلام"), " ").split(" ").filter { it.isNotEmpty() }

    /** How many words of [ours] are found in [theirs], in order: a longest common subsequence, never fewer than the importer's matching blocks. */
    private fun sharedWords(ours: List<String>, theirs: List<String>): Int {
        val table = Array(ours.size + 1) { IntArray(theirs.size + 1) }
        for (i in ours.indices) for (j in theirs.indices) {
            table[i + 1][j + 1] = if (ours[i] == theirs[j]) table[i][j] + 1 else maxOf(table[i][j + 1], table[i + 1][j])
        }
        return table[ours.size][theirs.size]
    }

    private fun namesCollector(folder: String, takhrij: String): Boolean =
        if (takhrij == "متفق عليه") folder == "Bukhari" || folder == "Muslim"
        else comparable(collectorOf.getValue(bookOf.getValue(folder))) in comparable(takhrij)

    @Test
    fun theNarratorsAreOnlyThoseOfTheChainsAndEachIsNamed() {
        assertEquals(seed.narrators.size, narrators.size)
        assertEquals(seed.edges.map { it.narratorId }.toSet(), narrators.keys)
        seed.narrators.forEach {
            assertTrue("narrator ${it.id}: name", it.primaryName.isNotBlank() && it.fullName.isNotBlank())
            assertEquals("a name is keyed by its normalized spelling", seed.narrators.count { o -> comparable(o.primaryName) == comparable(it.primaryName) }, 1)
        }
    }

    @Test
    fun aNarratorsTierIsStructural() {
        // A Companion ends some chain; a collector's teacher only ever opens one; everyone else is in between.
        val chains = seed.hadiths.map { edgesByHadith.getValue(it.id).map { link -> link.narratorId } }
        seed.narrators.forEach { narrator ->
            val ends = chains.any { it.last() == narrator.id }
            val onlyOpens = chains.all { narrator.id !in it || (it.first() == narrator.id) } && chains.none { narrator.id in it.drop(1) }
            val expected = if (ends) "صحابي" else if (onlyOpens) "شيخ المصنف" else "راوٍ"
            assertEquals("narrator ${narrator.id} ${narrator.primaryName}", expected, narrator.tier)
            assertTrue("narrator ${narrator.id} is no pivot: no dataset says so", !narrator.isPivot)
        }
    }

    @Test
    fun takhrijIsWhatTheSourceSaysAndNothingMore() {
        seed.hadiths.forEach { h ->
            val label = "${h.sourceBook} ${h.hadithNumber}"
            val note = comparable(rawByHadith.getValue(h.id).getJSONObject("source").optString("takhrijNote"))
            when {
                h.takhrij == "متفق عليه" -> assertTrue("$label: the note must cite both", "بخاري" in note && Regex("(^|\\s)و?مسلم(\\s|$)").containsMatchIn(note))
                h.takhrij.startsWith("رواه ") -> {
                    val cited = h.takhrij.removePrefix("رواه ").split(" و").map { comparable(it).removePrefix("ال") }
                    cited.forEach { collector ->
                        assertTrue("$label: the note does not name $collector", collector.removePrefix("ابن ").removePrefix("ابو ").let { it in note })
                    }
                }
                else -> assertTrue("$label: quoted as the author wrote it", h.takhrij.startsWith("رويناه") && comparable(h.takhrij).split(" ").all { it in note.split(" ") })
            }
        }
    }

    @Test
    fun everyHadithAndNarratorKeepsTheRowEveryEarlierCatalogGaveIt() {
        // Their ids are keys in users' databases (progress, chains, narrator history): a catalog may only add to them.
        val kept = selection.getJSONObject("arbainKeepIds")
        val byNumber = seed.hadiths.associateBy { it.hadithNumber }
        kept.keys().forEach { number -> assertEquals("Arba'in $number", kept.getLong(number), byNumber.getValue(number.toInt()).id) }
        assertEquals("the rest follow by number", (11L..52L).toList(), seed.hadiths.map { it.id }.sorted())
        assertEquals((14L..52L).toList(), seed.hadiths.filter { it.hadithNumber.toString() !in kept.keys().asSequence().toSet() }.sortedBy { it.hadithNumber }.map { it.id })

        val narratorIds = selection.getJSONObject("narratorKeepIds")
        narratorIds.keys().forEach { name -> assertEquals(name, narratorIds.getLong(name), seed.narrators.single { it.primaryName == name }.id) }
        // A narrator the chains added is numbered after the last one a catalog kept.
        val added = seed.narrators.filter { it.primaryName !in narratorIds.keys().asSequence().toSet() }
        assertTrue("a narrator is added after the kept ones", added.all { it.id > (narratorIds.keys().asSequence().maxOf { name -> narratorIds.getLong(name) }) })
    }

    // -- Groups ------------------------------------------------------------------------------

    @Test
    fun theGroupsFormATreeWithNamesInBothLanguages() {
        val byId = seed.groups.associateBy { it.id }
        assertEquals("duplicate group ids", seed.groups.size, byId.size)
        seed.groups.forEach { group ->
            assertTrue("group ${group.id}: Arabic title", group.title.isNotBlank())
            assertTrue("group ${group.id}: English title", group.titleEn.isNotBlank())
            assertTrue("group ${group.id}: parent ${group.parentId}", group.parentId == null || group.parentId in byId)
            // Walking up from any group reaches a book without meeting a group twice.
            val seen = mutableSetOf(group.id)
            var at = group.parentId
            while (at != null) {
                assertTrue("group ${group.id}: its parents run in a circle", seen.add(at))
                at = byId.getValue(at).parentId
            }
        }
        seed.groups.groupBy { it.parentId }.forEach { (parent, siblings) ->
            assertEquals("the sections of $parent share a position", siblings.size, siblings.map { it.position }.toSet().size)
        }
    }

    @Test
    fun theGroupsAreListedDepthFirstSoTheirOrderIsTheOrderOfTheShelves() {
        val children = seed.groups.groupBy { it.parentId }
        val depthFirst = buildList {
            fun visit(parent: Long?) {
                children[parent].orEmpty().sortedWith(compareBy({ it.position }, { it.id })).forEach {
                    add(it.id)
                    visit(it.id)
                }
            }
            visit(null)
        }

        assertEquals(depthFirst, seed.groups.map { it.id })
    }

    @Test
    fun everyHadithIsFiledInAGroupAndEveryBookWithoutSectionsHoldsSomething() {
        val groupIds = seed.groups.map { it.id }.toSet()
        seed.hadiths.forEach { assertTrue("${it.sourceBook} ${it.hadithNumber}: group ${it.groupId}", it.groupId in groupIds) }
        val parents = seed.groups.mapNotNull { it.parentId }.toSet()
        seed.groups.filter { it.id !in parents }.forEach { leaf ->
            assertTrue("group ${leaf.id} is empty", seed.hadiths.any { it.groupId == leaf.id })
        }
    }

    @Test
    fun theHadithsAreNumberedInTheOrderTheyAreTaught() {
        val rank = seed.groups.withIndex().associate { (index, group) -> group.id to index }
        val taught = seed.hadiths.sortedBy { it.position }

        assertEquals("positions run 1..n", (1..seed.hadiths.size).toList(), taught.map { it.position })
        // By book, then by the number in the book, then by id: so the order does not depend on how rows were numbered.
        assertEquals(seed.hadiths.sortedWith(compareBy({ rank.getValue(it.groupId!!) }, { it.hadithNumber }, { it.id })).map { it.id }, taught.map { it.id })
    }

    @Test
    fun theSelectionFilesEveryBookTheSeedHasUnderTheGroupItWas() {
        val bookGroups = selection.getJSONObject("bookGroups")
        seed.hadiths.forEach { assertEquals("${it.sourceBook} ${it.hadithNumber}", bookGroups.getLong(it.sourceBook), it.groupId) }
        val chosen = selection.getJSONArray("groups")
        assertEquals(seed.groups.map { it.id }.toSet(), List(chosen.length()) { chosen.getJSONObject(it).getLong("id") }.toSet())
        // A shipped group id is a key in users' databases: it is never renumbered, so these are pinned.
        assertEquals(1L, seed.groups.single { it.title == "الأربعون النووية" }.id)
    }

    @Test
    fun theSeedIsTiedToThePinnedSourceAndOnlyThat() {
        val sources = snapshot.getJSONObject("sources")
        val pinned = raw.getJSONObject("provenance").getJSONObject("sources")
        assertEquals(sources.keys().asSequence().toSet(), pinned.keys().asSequence().toSet())
        sources.keys().forEach { repo ->
            assertTrue("$repo is pinned to a full commit", Regex("[0-9a-f]{40}").matches(sources.getJSONObject(repo).getString("commit")))
            assertEquals(sources.getJSONObject(repo).getString("commit"), pinned.getJSONObject(repo).getString("commit"))
        }
        seed.hadiths.forEach { h ->
            val dataset = rawByHadith.getValue(h.id).getJSONObject("source").getString("dataset")
            assertTrue("${h.sourceBook} ${h.hadithNumber}: from $dataset", dataset in pinned.keys().asSequence().toSet())
        }
    }
}
